package com.jijilabsdigital.swell.protocol

import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/** The shared vectors in docs/protocol-vectors/ (spec 13, A.12), generated by the Swift code and replayed here byte for byte. */
object Vectors {
    val dir: File by lazy {
        var d: File? = File(System.getProperty("user.dir")).absoluteFile
        while (d != null && !File(d, "docs/protocol-vectors").isDirectory) d = d.parentFile
        File(d ?: error("docs/protocol-vectors not found above ${System.getProperty("user.dir")}"), "docs/protocol-vectors")
    }

    val FILES = listOf("backup.json", "group-state.json", "handshake-conversation.json", "identity.json", "invite.json",
        "kdf.json", "link.json", "mlkem768.json", "report.json", "signature.json")

    fun load(name: String): JSONObject = JSONObject(File(dir, name).readText())

    fun hex(s: String): ByteArray {
        // "xx*n" is the fill notation of kdf.json.
        val star = s.indexOf('*')
        if (star == 2) return ByteArray(s.substring(3).toInt()) { s.substring(0, 2).toInt(16).toByte() }
        require(s.length % 2 == 0) { "hex length" }
        return ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
    }

    fun ByteArray.hx(): String = joinToString("") { "%02x".format(it) }
    fun JSONObject.b(key: String): ByteArray = hex(getString(key))
    fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }
    fun JSONArray.strings(): List<String> = (0 until length()).map { getString(it) }
    fun rep(v: Int, n: Int): ByteArray = ByteArray(n) { v.toByte() }

    /** Recorded randomness (A.12): fixed chunks in order, then recorded ML-KEM encapsulations in order. */
    class Replay(chunks: List<ByteArray>, kems: List<SP.KemEncapsulation> = emptyList()) : SPEntropy {
        private val chunks = ArrayDeque(chunks)
        private val kems = ArrayDeque(kems)
        val left: Int get() = chunks.size + kems.size

        override fun bytes(n: Int): ByteArray {
            val c = chunks.removeFirstOrNull() ?: error("no recorded chunk left for $n bytes")
            check(c.size == n) { "recorded chunk has ${c.size} bytes, $n drawn" }
            return c
        }

        override fun encapsulate(ek: ByteArray): SP.KemEncapsulation = kems.removeFirstOrNull() ?: error("no recorded encapsulation left")

        companion object {
            fun of(o: JSONObject): Replay = Replay(o.getJSONArray("chunks").strings().map(::hex),
                o.optJSONArray("kem")?.objects()?.map { SP.KemEncapsulation(it.b("ct"), it.b("ss")) } ?: emptyList())
        }
    }
}
